import{_ as a,o as t,c as i,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"ADR-004 — Spring Cloud Gateway làm API Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-004-spring-cloud-gateway.md","filePath":"adr/ADR-004-spring-cloud-gateway.md"}'),n={name:"adr/ADR-004-spring-cloud-gateway.md"};function o(r,e,s,l,h,d){return t(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="adr-004-—-spring-cloud-gateway-lam-api-gateway" tabindex="-1">ADR-004 — Spring Cloud Gateway làm API Gateway <a class="header-anchor" href="#adr-004-—-spring-cloud-gateway-lam-api-gateway" aria-label="Permalink to &quot;ADR-004 — Spring Cloud Gateway làm API Gateway&quot;">​</a></h1><p><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Client (web-dashboard, mobile-app) cần 1 entry point duy nhất vào hệ thống thay vì gọi trực tiếp từng service (business-service:8081, ai-service:8082, publisher-service:8083). Cần chọn công nghệ gateway.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Dùng <strong>Spring Cloud Gateway</strong> làm <code>api-gateway</code>, đảm nhận: verify chữ ký JWT (RS256, public key), check revoke qua Redis blacklist, rate limiting theo <code>X-User-Id</code>. Gateway forward nguyên request sau khi verify — <strong>không</strong> tự làm RBAC theo role (xem <code>docs/architecture/architecture.html</code> mục &quot;Auth Role-Check Flow&quot;).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Tích cực:</strong></p><ul><li>Cùng ngôn ngữ/ecosystem (Java/Spring) với <code>business-service</code>, <code>publisher-service</code> — team dễ maintain, tái sử dụng thư viện JWT chung.</li><li>Tách rõ trách nhiệm: gateway chỉ verify chữ ký + rate limit (perimeter security), business-service tự re-verify JWT + query DB lấy role hiện tại (<code>RequireRoleAspect</code>) — tránh gateway phải biết nghiệp vụ RBAC 2 tầng (Agency-level + Workspace-level) phức tạp của V2.</li><li>Route theo path-prefix wildcard (<code>/api/v1/**</code>) — thêm endpoint mới trong business-service tự động qua gateway, không cần sửa <code>application.yml</code> mỗi lần thêm API.</li></ul><p><strong>Tiêu cực:</strong></p><ul><li>Gateway chỉ khai báo route cho <code>business-service</code> hiện tại — <code>ai-service</code>/<code>publisher-service</code> chưa có route riêng qua gateway (không public trực tiếp, chỉ nội bộ), cần bổ sung route khi có yêu cầu public endpoint cho 2 service này.</li><li>Không phải service discovery động (Eureka/Consul) — thêm service mới phải sửa tay <code>application.yml</code>, không tự động phát hiện.</li><li>RBAC 2 tầng V2 (Agency-level check tách biệt Workspace-level <code>@RequireRole</code>) đặt toàn bộ ở business-service — nếu sau này thêm service khác cần enforce Agency-level permission, phải duplicate logic hoặc factor ra shared library.</li></ul>',11)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
